y=$(date +%Y); m=$(date +%m); { printf '{"blocks":[{"type":"header","text":{"type":"plain_text","text":"%s年%s月 カレンダー"}},{"type":"section","text":{"type":"mrkdwn","text":"今月のカレンダー表示（column_settings使用）"}},{"type":"table","column_settings":[{"align":"center"},{"align":"center"},{"align":"center"},{"align":"center"},{"align":"center"},{"align":"center"},{"align":"center"}],"rows":[[{"type":"raw_text","text":"日"},{"type":"raw_text","text":"月"},{"type":"raw_text","text":"火"},{"type":"raw_text","text":"水"},{"type":"raw_text","text":"木"},{"type":"raw_text","text":"金"},{"type":"raw_text","text":"土"}]'; cal "$m" "$y" | tail -n +3 | sed 's/^/ /' | awk '{for(i=1;i<=7;i++){if(i<=NF)printf(",[{\"type\":\"raw_text\",\"text\":\"%s\"}%s", $i,(i<7?",":""));else printf(",[{\"type\":\"raw_text\",\"text\":\"\"}%s",(i<7?",":""));} printf("]")}'; printf ']},{"type":"context","elements":[{"type":"mrkdwn","text":"Slackのtableブロックで今月（%s年%s月）のカレンダーを表示します。"}]}]}\n' "$y" "$((10#$m))"; } | xargs